GetClassDetails:
query GetClassDetails(
    $year: Int!
    $semester: Semester!
    $sessionId: SessionIdentifier!
    $subject: String!
    $courseNumber: CourseNumber!
    $number: ClassNumber!
  ) {
    class(
      year: $year
      semester: $semester
      sessionId: $sessionId
      subject: $subject
      courseNumber: $courseNumber
      number: $number
    ) {
      year
      semester
      subject
      sessionId
      courseNumber
      courseId
      number
      unitsMax
      unitsMin
      finalExam
      decal {
        title
      }
      course {
        title
        description
        requirements
        aggregatedRatings(metricNames: [Attendance, Recording]) {
          metrics {
            metricName
            count
            weightedAverage
            categories {
              value
              count
            }
          }
        }
        gradeDistribution {
          average
          pnpPercentage
        }
      }
      primarySection {
        sectionId
        component
        sectionAttributes(attributeCode: "NOTE") {
          attribute {
            code
            formalDescription
          }
          value {
            description
            formalDescription
          }
        }
        exams {
          date
          startTime
          endTime
          location
          type
        }
        enrollment {
          latest {
            endTime
            enrolledCount
            maxEnroll
            waitlistedCount
            maxWaitlist
            activeReservedMaxCount
            seatReservationCount {
              enrolledCount
              maxEnroll
              requirementGroup {
                description
              }
              isValid
            }
          }
        }
        meetings {
          days
          location
          endTime
          startTime
          instructors {
            familyName
            givenName
          }
        }
      }
      decal {
        syllabus
        description
        syllabusUrl
        applicationUrl
        applicationDueDate
        instructors {
          name
          email
        }
      }
    }
  }

GetCourse:
query GetCourse($subject: String!, $number: CourseNumber!) {
    course(subject: $subject, number: $number) {
      courseId
      subject
      number
      title
      description
      academicCareer
      gradeDistribution {
        average
        distribution {
          letter
          count
        }
      }
      gradingBasis
      finalExam
      requirements
      requiredCourses {
        subject
        number
      }
      classes {
        year
        semester
        number
      }
      aggregatedRatings {
        metrics {
          metricName
          count
          weightedAverage
          categories {
            value
            count
          }
        }
      }
    }
  }

GetCourseWithInstructor:
query GetCourseWithInstructor(
    $subject: String!
    $number: CourseNumber!
    $includeFormerNames: Boolean = false
  ) {
    course(subject: $subject, number: $number) {
      classes(includeFormerNames: $includeFormerNames) {
        year
        semester
        number
        subject
        courseNumber
        sessionId
        anyPrintInScheduleOfClasses
        term {
          temporalPosition
        }
        primarySection {
          enrollment {
            latest {
              enrolledCount
            }
          }
          startDate
          meetings {
            instructors {
              familyName
              givenName
            }
          }
          number
        }
        gradeDistribution {
          average
        }
      }
    }
  }

GetCourseNames:
query GetCourseNames {
    courses {
      courseId
      subject
      departmentNicknames
      formerNames
      number
      title
    }
  }

GetClassRatingsData:
query GetClassRatingsData(
    $subject: String!
    $courseNumber: String!
    $courseNumberTyped: CourseNumber!
  ) {
    course(subject: $subject, number: $courseNumberTyped) {
      subject
      number
      aggregatedRatings {
        metrics {
          metricName
          count
          weightedAverage
          categories {
            value
            count
          }
        }
      }
      instructorAggregatedRatings {
        instructor {
          givenName
          familyName
        }
        aggregatedRatings {
          metrics {
            metricName
            count
            weightedAverage
            categories {
              value
              count
            }
          }
        }
      }
      classes(printInScheduleOnly: true) {
        semester
        year
        number
        anyPrintInScheduleOfClasses
        primarySection {
          startDate
          meetings {
            instructors {
              familyName
              givenName
            }
          }
        }
      }
    }
    semestersWithRatings(subject: $subject, courseNumber: $courseNumber) {
      semester
      year
      maxMetricCount
    }
  }

GetAllRatings:
query GetAllRatings {
    allRatings {
      anonymousUserId
      subject
      courseNumber
      semester
      year
      classNumber
      metricName
      value
      createdAt
    }
  }

GetClassReviews:
query GetClassReviews($subject: String!, $courseNumber: String!) {
    classReviews(subject: $subject, courseNumber: $courseNumber) {
      subject
      courseNumber
      count
      users {
        anonymousUserId
        classes {
          subject
          courseNumber
          semester
          year
          classNumber
          professorName
          metrics {
            metricName
            value
          }
          reviewTitle
          reviewContent
          reviewerGrade
          lastUpdated
          reviewId
          helpfulCount
        }
      }
    }
  }
